      SUBROUTINE CLI(LOGIC)CC     CHECK TO SEE IF CONSTRAINT IS ONE SIDEDCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'CC     LOCAL VARIABLESC      LOGICAL  LOGICCC----------------------------------------------------------------------C     ELIMINATE CONSTRAINT IF NOT APPLICABLEC      LOGIC  =  .FALSE.      IF (CTY .EQ. 0) GO TO 10      IF ((CTY .EQ. 1) .AND. (A(1) .GT. 0.0)) GO TO 10      IF ((CTY .EQ. 2) .AND. (A(1) .LT. 0.0)) GO TO 10      A(1) = 0.0      NC = NC - 1      LOGIC  =  .TRUE.C   10 RETURN      END